use std::{collections::BTreeMap,path::Path};use artifactum_core::{provider_error,AcquireContext,Acquisition,AcquisitionPlan,ArtifactPath,ArtifactProvider,ArtifactRequirement,ProviderCapabilities,ProviderDescriptor,ResolveContext,ResolvedFile,ResolvedRevision,Resolution};use artifactum_provider_api::{apply_headers,bearer_headers,client,json,plan,profile_value};use async_trait::async_trait;
#[derive(Clone,Debug,Default)]pub struct ZenodoProvider;
#[async_trait]impl ArtifactProvider for ZenodoProvider{fn descriptor(&self)->ProviderDescriptor{ProviderDescriptor{name:"zenodo".into(),version:env!("CARGO_PKG_VERSION").into(),schemes:vec!["zenodo".into()],capabilities:ProviderCapabilities{resolve:true,acquire:true,list:true,auth:true,..Default::default()},metadata:Default::default()}}async fn resolve(&self,r:&ArtifactRequirement,c:&ResolveContext)->artifactum_core::Result<Resolution>{if c.offline{return Err(provider_error("zenodo","cannot resolve while offline"));}let id=r.reference.locator();let base=profile_value(c,"api_base").unwrap_or("https://zenodo.org/api").trim_end_matches('/');let headers=bearer_headers(c.profile.as_ref(),"token_env","ZENODO_TOKEN");let response=apply_headers(client()?.get(format!("{base}/records/{id}")),&headers).send().await.map_err(|e|provider_error("zenodo",e))?;let value=json("zenodo",response).await?;let selection=r.selection.compile()?;let mut files=Vec::new();for f in value.get("files").and_then(|v|v.as_array()).into_iter().flatten(){let key=f.get("key").and_then(|v|v.as_str()).ok_or_else(||provider_error("zenodo","record file missing key"))?;if !selection.matches(key){continue}let url=f.pointer("/links/content").or_else(||f.pointer("/links/self")).and_then(|v|v.as_str()).ok_or_else(||provider_error("zenodo","record file missing download link"))?;let mut digests=artifactum_core::DigestSet::default();if let Some(sum)=f.get("checksum").and_then(|v|v.as_str()){if let Some((alg,val))=sum.split_once(':'){digests.0.insert(alg.into(),val.into());}}files.push(ResolvedFile{path:ArtifactPath::new(key)?,size:f.get("size").and_then(|v|v.as_u64()),digests,media_type:None,source:serde_json::json!({"url":url})});}let rev=value.get("revision").or_else(||value.get("id")).and_then(|v|v.as_u64()).map(|v|v.to_string()).or_else(||Some(id.into()));Ok(Resolution{provider:"zenodo".into(),canonical_ref:format!("zenodo:{id}"),revision:rev.map(|id|ResolvedRevision{id,requested:r.revision.clone()}),files,provider_state:serde_json::Value::Null,metadata:BTreeMap::new()})}async fn prepare_acquisition(&self,f:&ResolvedFile,c:&AcquireContext)->artifactum_core::Result<AcquisitionPlan>{let url=f.source.get("url").and_then(|v|v.as_str()).ok_or_else(||provider_error("zenodo","missing download URL"))?;let headers=bearer_headers(c.profile.as_ref(),"token_env","ZENODO_TOKEN");Ok(plan(url,headers))}}
pub fn provider()->ZenodoProvider{ZenodoProvider}
